"""Build A2A ``AgentCard`` skills from a Mantle :class:`SkillCatalog`.

The card is the Mantle counterpart of the CALM flow-based card in
:mod:`rasa.core.a2a_server.agent_card_generator`. The card shell (name,
``supportedInterfaces``, capabilities) is shared; only the skill list comes
from the catalog.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Optional

from a2a.types import AgentCard, AgentSkill

from rasa.core.a2a_server.agent_card_generator import AgentCardGenerator
from rasa.core.a2a_server.config import A2AServerSettings
from rasa.mantle.a2a.task_state import is_user_facing_skill

if TYPE_CHECKING:
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.mantle.skills.skill import Skill


class SkillCatalogCardSource:
    """Choose which catalog skills an orchestrator may route to over A2A.

    A skill is advertised when the Mantle router itself may activate it: it is
    not ``engine_managed``, ``disabled``, or ``hidden``, and it exposes at
    least one routable target. Bundled default skills (``is_default``) are
    left off the card unless ``include_default_skills`` is on. Even then, a
    default skill appears only when a project override made it routable by
    clearing ``routing.engine_managed``; every bundled default ships
    engine-managed.
    """

    def __init__(
        self,
        catalog: "SkillCatalog",
        *,
        include_default_skills: bool = False,
    ) -> None:
        """Bind a loaded catalog and the Mantle card option."""
        self._catalog = catalog
        self.include_default_skills = include_default_skills

    def advertised_skills(self) -> list["Skill"]:
        """Catalog skills that go on the card, sorted by id."""
        routable_ids = self._catalog.routable_entries({})
        advertised = []
        for skill_id in routable_ids:
            skill = self._catalog.skills[skill_id]
            # Same predicate mapping and cancel use, so an advertised default
            # stays user-facing for the rest of the task.
            if not is_user_facing_skill(
                skill, include_default_skills=self.include_default_skills
            ):
                continue
            advertised.append(skill)
        return sorted(advertised, key=lambda skill: skill.id)

    def skills(self) -> list[AgentSkill]:
        """AgentCard skills for :meth:`advertised_skills`."""
        return [self._skill_from_catalog(skill) for skill in self.advertised_skills()]

    def card(
        self,
        settings: A2AServerSettings,
        *,
        port: Optional[int] = None,
        interface: Optional[str] = None,
        scheme: Optional[str] = None,
        assistant_name: Optional[str] = None,
        version: str = "1.0.0",
    ) -> AgentCard:
        """Full card: catalog skills in the shared shell.

        ``supportedInterfaces`` carries the JSON-RPC URL from *settings*, which
        the Mantle config source read from ``integrations.yml``. Both the 1.0
        and the 0.3 JSON-RPC bindings point at that one URL, so the hybrid
        card an orchestrator fetches still has a top-level ``url``.
        """
        return AgentCardGenerator.card_from_skills(
            settings,
            self.skills(),
            port=port,
            interface=interface,
            scheme=scheme,
            assistant_name=assistant_name,
            version=version,
        )

    @staticmethod
    def _skill_from_catalog(skill: "Skill") -> AgentSkill:
        name = skill.name or skill.id
        return AgentSkill(
            id=skill.id,
            name=name,
            description=skill.description or name,
            tags=[skill.id],
        )
